head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.vScrenID = "ULDSTF05915.xml";
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.haltTpCd = "", scwin.gubun = "";
scwin.trsIdx; // insert, update 구분

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_search = function() {
    if (scwin.fr_bz_procs_no != "") {
        var url = "/tradingSuspension.do?method=searchTradingSuspension" + "&DIV_IDX=" + DIV_IDX_ASGN + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Mst.DataID = encodeURI(url);
        dts_Mst.reset();
        url = "/tradingSuspension.do?method=searchTradingSuspension" + "&DIV_IDX=" + DIV_IDX_ISU_ELW + "&ISUR_CD=" + scwin.Isur_cd + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_Isu.DataID = encodeURI(url);
        dts_Isu.reset();
        url = "/tradingSuspension.do?method=searchTradingSuspension" + "&DIV_IDX=" + DIV_IDX_RASN_ELW + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_Rsn.DataID = encodeURI(url);
        dts_Rsn.reset();
        url = "/tradingSuspension.do?method=searchTradingSuspension" + "&DIV_IDX=" + DIV_IDX_RASN_ULY + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_Rsn_Uly.DataID = encodeURI(url);
        dts_Rsn_Uly.reset();
    }
};
scwin.fn_new_onload = function() {
    /* useupdate를 false로 지정함. */
    var url = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=TRD_SUSP_INOUT";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //dts_Mst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=TRD_SUSP_INOUT";
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();

    /* useupdate를 false로 지정함. */
    dts_Rsn.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=TRD_SUSP_RSN_INOUT";
    dts_Rsn.reset();
    dts_Rsn_Uly.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=TRD_SUSP_RSN_INOUT";
    dts_Rsn_Uly.reset();

    /* useupdate를 false로 지정함. */
    dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CODE_ELW_OUT";
    dts_Isu.reset();
};
scwin.fn_GetParRsnCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = "1";
    arrPar[1] = "06";
    return arrPar.length;
};
scwin.fn_SetParRsnCd = function(arrPar) {
    //선택된 사유코드 중복체크
    if (!$c.lc.fn_isNewValueForDataSet(dts_Rsn, "LD_HALT_RSN_CD", arrPar[0])) return;
    dts_Rsn.insertRow();
    dts_Rsn.setCellData(dts_Rsn.getRowPosition(), "LD_HALT_RSN_CD", arrPar[0]);
    dts_Rsn.setCellData(dts_Rsn.getRowPosition(), "HALT_RSN_NM", arrPar[1]);
    txb_TrdHaltGrndRegulNm.setValue(arrPar[2]);
};
scwin.fn_SetParRsnUlyCd = function(arrPar) {
    //선택된 사유코드 중복체크
    if (!$c.lc.fn_isNewValueForDataSet(dts_Rsn_Uly, "LD_HALT_RSN_CD", arrPar[0])) return;
    dts_Rsn_Uly.insertRow();
    dts_Rsn_Uly.setCellData(dts_Rsn_Uly.getRowPosition(), "LD_HALT_RSN_CD", arrPar[0]);
    dts_Rsn_Uly.setCellData(dts_Rsn_Uly.getRowPosition(), "HALT_RSN_NM", arrPar[1]);
};
scwin.fn_GetParIsu = function(arrPar, param_dts) {
    arrPar[0] = scwin.Isur_cd;
    arrPar[1] = scwin.gubun;
    $c.stf.CopyDataSet(dts_Isu, param_dts);
};
scwin.fn_SetParIsu = function(param_dts) {
    //alert(dts_Isu.text);
    $c.stf.CopyDataSet(param_dts, dts_Isu);
    //alert(dts_Isu.text);

};
scwin.fn_CheckForm = function() {
    if (dts_Isu.getTotalRow() == 0) {
        $c.win.alert("[거래정지종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }
    if (!$c.lc.checkDdTm("DD", edt_TrdHaltStrtDd, "거래정지 지정", false)) return false;
    if (edt_TrdHaltEndDd.getValue() == "" && txb_TrdHaltEndDdDsc.getValue() == "") {
        $c.win.alert("[거래정지해제일] 또는 [주석]을 입력하세요.");
        txb_TrdHaltEndDdDsc.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_TrdHaltEndDdDsc, 2000, "주석")) return false;
    if (edt_TrdHaltEndDd.getValue() != "" && (edt_TrdHaltStrtDd.getValue() >= edt_TrdHaltEndDd.getValue())) {
        $c.win.alert("[거래정지 해제일]은  [거래정지 지정일]이후로 입력하세요.");
        edt_TrdHaltEndDd.focus();
        return false;
    }
    if (dts_Rsn.getTotalRow() == 0) {
        $c.win.alert("[정지사유]를 선택하세요.");
        btn_rsn_add.focus();
        return false;
    }
    if (!$c.stf.checkEmptyValue(txb_TrdHaltGrndRegulNm, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txb_TrdHaltGrndRegulNm, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;
    if (scwin.gubun == '2' && dts_Rsn_Uly.getTotalRow() == 0) {
        $c.win.alert("[기초자산의 정지사유]를 선택하세요.");
        btn_rsn_uly_add.focus();
        return false;
    }
    return true;
};
scwin.fn_save_trs = function() {
    //매매거래정지 사유는 매번 업무처리 번호를 세팅함
    //사유별 추가,삭제가 있을수 있기때문
    for (var i = 1; i <= dts_Rsn.getTotalRow(); i++) {
        dts_Rsn.setCellData(i, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
        dts_Rsn.setCellData(i, "ULY_HALT_YN", "N");
    }
    for (var i = 1; i <= dts_Rsn_Uly.getTotalRow(); i++) {
        dts_Rsn_Uly.setCellData(i, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
        dts_Rsn_Uly.setCellData(i, "ULY_HALT_YN", "Y");
    }


    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        /*ORG SRC: dts_Isu.NameString(i, "BZ_PROCS_NO") = fr_bz_procs_no;*/
        X = scwin.fr_bz_procs_no;
    }


    // ELW는 항상  종목별기준으로 처리함
    // 1 : 종목별 , 2 : 법인별
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "1");
    var vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx == TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx == TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.Action = $c.lc.fn_encodeNSession("/tradingSuspension.do?method=saveTradingSuspension&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD);
    trs.KeyName = "toinb_dataid4";
    trs.KeyValue = "JSP(I: dtsParm1= dts_Mst , I:dtsParm2= dts_Isu, I:dtsParm3= dts_Rsn, I:dtsParm4= dts_Rsn_Uly)";
    trs.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.fr_bz_procs_no + ",COUNT=4" + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_215 + ",DIV_IDX[0]=" + DIV_IDX_ASGN + ",DIV_IDX[1]=" + DIV_IDX_ISU_ELW + ",DIV_IDX[2]=" + DIV_IDX_RASN_ELW + ",DIV_IDX[3]=" + DIV_IDX_RASN_ULY;
    trs.Post();
};
scwin.fn_save = function() {
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "HALT_DESNRELS_TP_CD", scwin.haltTpCd);
            dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
            scwin.fn_save_trs();
        }
    }
};
scwin.fn_update = function() {
    if (scwin.fn_CheckForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        scwin.fn_save_trs();
    }
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_save_trs();
};
scwin.fn_dscl = async function() {
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        if (scwin.gubun == '1') {
            // 발행사 기준
            arr[0] = "68954E";
        } else if (scwin.gubun == '2') {
            // 기초자산 기준
            arr[0] = "68954F";
        }
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';
        //arr[4]; //ctnt
        arr[5] = $c.lc.fn_GetAddTitle(dts_Mst.getCellData(dts_Mst.getRowPosition(), "COM_NM")); //add  title

        $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
        $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
        $c.stf.CopyDataSet(dts_Rsn, param_dts2);
        $c.stf.CopyDataSet(dts_Rsn_Uly, param_dts3);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "TGT_NM", scwin.Isur_nm);
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 740 + 5;
    var hgt = 790 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_drft = function() {

};
scwin.fn_makt = function() {

};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_search;
    fr_fn_list_sync();
};
scwin.trs_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh(); // 목록 다시 조회

    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_search();
    }
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_Rsn_OnLoadError = function() {
    $c.stf.alert_error(dts_Rsn);
};
scwin.dts_Mst_OnLoadError = function() {
    $c.stf.alert_error(dts_Mst);
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    if (scwin.fr_bz_procs_no == "") {
        dts_Mst.insertRow();
    }

    // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (scwin.fr_bz_procs_no == "") {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_TrdHaltStrtDd, false);
    }
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {

};
scwin.img_SetIsuCd_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsu;
    scwin.fn_SetPar = fn_SetParIsu;
    $c.lc.fn_PopFindElwCode();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_SetTrdHaltStrtDd_onclick = function() {
    popUpCalendar2(edt_TrdHaltStrtDd);
};
scwin.btn_rsn_add_onclick = function() {
    scwin.fn_GetPar = fn_GetParRsnCd;
    scwin.fn_SetPar = fn_SetParRsnCd;
    $c.lc.fn_PopFindLstRsnCd(RSNCD_SUSP);
};
scwin.btn_rsn_del_onclick = function() {
    $c.cp.removeRow(dts_Rsn, dts_Rsn.getRowPosition());
};
scwin.btn_rsn_uly_add_onclick = function() {
    if (scwin.gubun == '1') {
        $c.win.alert($c.stf.getMessageParam("MSG-0012", ""));
        return;
    }
    scwin.fn_GetPar = fn_GetParRsnCd;
    scwin.fn_SetPar = fn_SetParRsnUlyCd;
    $c.lc.fn_PopFindLstRsnCd(RSNCD_SUSP);
};
scwin.btn_rsn_uly_del_onclick = function() {
    $c.cp.removeRow(dts_Rsn_Uly, dts_Rsn.getRowPosition());
};
scwin.image_1_onclick = function() {
    popUpCalendar2(edt_TrdHaltEndDd);
};
scwin.gform_onload = function() {
    var fnc = $c.frame.path("../").scwin.fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
    var arrPar = new Array();
    if (fnc != undefined) {
        fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
        scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
        scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
        scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
        scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
        scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
        scwin.haltTpCd = (arrPar.length >= 6 ? arrPar[5] : ""); // 거래정지지정및해제구분코드
        scwin.gubun = (arrPar.length >= 7 ? arrPar[6] : ""); // 발행사/기초자산 구분값

    }

    //alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" + 
    //		 "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  ) ;

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

    if (scwin.fr_bz_procs_no != "") {
        // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
        scwin.fn_search();
    } else {
        scwin.fn_new_onload(); // 신규작성시 호출

    }
    $c.libRoundPanel.PanelToGroupBox(panel_3);
};
